{{ config(tags=['publication_guard']) }}
with entries as (select arrayJoin(JSONExtractArrayRaw({{ ch_literal(var('publication_quality_json','[]')) }})) as item), parsed as (select JSONExtractString(item,'measure_id') as id, JSONExtractString(item,'availability_status') as status,JSONExtract(item,'availability_reason','Nullable(String)') as reason,JSONExtract(item,'nb_expected','Nullable(UInt64)') as expected,JSONExtract(item,'nb_known','Nullable(UInt64)') as known from entries) select 'invalid_quality_registry' as failure from parsed having count()!=30 or uniqExact(id)!=30 or countIf(id not in ('objectives.mrr_signed','objectives.pipeline_generated','objectives.pipeline_weighted','objectives.demos','funnel.opportunities','funnel.transition','funnel.global','revenue.active_mrr','revenue.new_mrr','revenue.churn_mrr','revenue.active_clients','durations.completed','durations.current_age','durations.threshold','cohorts.outcomes','pipeline.open_count','pipeline.open_amount','pipeline.weighted_amount','pipeline.coverage','pipeline.stagnation','pipeline.in_demo','events.generated_count','events.generated_amount','events.signed_count','events.signed_mrr','events.cycle','actions.requests','actions.realized_demos','demo_intervals.duration','timeline.detail'))>0 or countIf(status not in ('available','partial','blocked_definition','blocked_evidence','non_mature','not_observable','not_applicable'))>0 or countIf(status!='available' and reason is null)>0 or countIf(known>expected)>0 or countIf(id in ('objectives.mrr_signed','objectives.pipeline_generated','objectives.pipeline_weighted','objectives.demos','events.signed_mrr','events.generated_amount','pipeline.open_amount','pipeline.weighted_amount','actions.realized_demos','demo_intervals.duration','pipeline.coverage') and status='available')>0
